parameters.inputText:
=You are an AI business inquiry classifier for a B2B company. Analyze the following inquiry and return a JSON object.

Inquiry:
- Name: {{ $json.body.name }}
- Email: {{ $json.body.email }}
- Company: {{ $json.body.company }}
- Message: {{ $json.body.message }}

Return ONLY a valid JSON object with these fields:
{
  "intent": "<one of: purchase, partnership, support, general, spam>",
  "urgency": "<one of: high, medium, low>",
  "fit_score": <number 1-10>,
  "summary": "<one sentence summary>",
  "suggested_action": "<what the sales/ops team should do next>",
  "category": "<one of: enterprise, smb, individual, unknown>"
}

parameters.jsCode:
// Parse the AI response and merge with original inquiry data
const items = $input.all();
const results = [];

for (const item of items) {
  const aiResponse = item.json.text || item.json.output || '';

  // Extract JSON from the AI response
  let classification = {};
  try {
    const jsonMatch = aiResponse.match(/\{[\s\S]*\}/);
    if (jsonMatch) {
      classification = JSON.parse(jsonMatch[0]);
    }
  } catch (e) {
    classification = {
      intent: 'general',
      urgency: 'medium',
      fit_score: 5,
      summary: 'Could not parse AI classification',
      suggested_action: 'Manual review required',
      category: 'unknown'
    };
  }

  // Get the original inquiry from the webhook
  const webhook = $('Inquiry Webhook').first().json;
  const body = webhook.body || webhook;

  results.push({
    json: {
      // Original inquiry fields
      name: body.name || '',
      email: body.email || '',
      company: body.company || '',
      message: body.message || '',
      received_at: new Date().toISOString(),

      // AI classification fields
      intent: classification.intent || 'general',
      urgency: classification.urgency || 'medium',
      fit_score: classification.fit_score || 5,
      summary: classification.summary || '',
      suggested_action: classification.suggested_action || '',
      category: classification.category || 'unknown',
      status: 'New',

      // Full AI response for debugging
      ai_raw: aiResponse
    }
  });
}

return results;

