parameters.jsCode:
// Transform Airtable records into the format the dashboard expects
const items = $input.all();
const customers = items.map((item, index) => {
  const fields = item.json.fields || item.json;
  return {
    id: item.json.id || String(index + 1),
    name: fields.Name || fields.name || 'Unknown',
    email: fields.Email || fields.email || '',
    status: fields.Status || fields.status || 'New',
    last_active: fields['Received At'] || fields.received_at || new Date().toISOString(),
    company: fields.Company || fields.company || '',
    intent: fields.Intent || fields.intent || '',
    urgency: fields.Urgency || fields.urgency || '',
    fit_score: fields['Fit Score'] || fields.fit_score || 0,
    summary: fields.Summary || fields.summary || '',
    suggested_action: fields['Suggested Action'] || fields.suggested_action || ''
  };
});

return [{ json: { customers } }];
